    --data "{
    \"property_id\": 16,
    \"owner_id\": 16,
    \"tenant_user_id\": 16,
    \"status\": \"active\",
    \"is_renewable\": false,
    \"search\": \"n\",
    \"start_date\": \"2026-08-09T17:25:49\",
    \"end_date\": \"2026-08-09T17:25:49\",
    \"sort_by\": \"start_date\",
    \"sort_order\": \"asc\",
    \"perPage\": 7
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/dashboard/properties/5/rental-cards/history"
);

const params = {
    "page": "1",
    "perPage": "15",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Authorization": "Bearer 14|gLxqLsZPXA3iPR6M5GGWMqoNZn494yCoti2IqnKs971c1382",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "property_id": 16,
    "owner_id": 16,
    "tenant_user_id": 16,
    "status": "active",
    "is_renewable": false,
    "search": "n",
    "start_date": "2026-08-09T17:25:49",
    "end_date": "2026-08-09T17:25:49",
    "sort_by": "start_date",
    "sort_order": "asc",
    "perPage": 7
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

